package dev.vaadin.agentdemo.base.ui;

import com.vaadin.flow.component.applayout.AppLayout;
import com.vaadin.flow.component.applayout.DrawerToggle;
import com.vaadin.flow.component.html.H1;
import com.vaadin.flow.component.html.Header;
import com.vaadin.flow.component.icon.Icon;
import com.vaadin.flow.component.orderedlayout.Scroller;
import com.vaadin.flow.component.sidenav.SideNav;
import com.vaadin.flow.component.sidenav.SideNavItem;
import com.vaadin.flow.router.AfterNavigationEvent;
import com.vaadin.flow.router.AfterNavigationObserver;
import com.vaadin.flow.router.Layout;
import com.vaadin.flow.server.menu.MenuConfiguration;
import com.vaadin.flow.server.menu.MenuEntry;

/**
 * The application shell. The drawer holds the application name above the
 * navigation, which is generated from the {@code @Menu} annotations of the
 * views. The navbar shows the drawer toggle followed by the name of the
 * current view.
 */
@Layout
public class MainLayout extends AppLayout implements AfterNavigationObserver {

    private final H1 viewTitle = new H1();

    public MainLayout() {
        // The drawer is the full-height section, so the navbar starts at the
        // left edge of the content area instead of the viewport.
        setPrimarySection(Section.DRAWER);

        var appName = new H1("Vaadin Agent Demo");
        appName.addClassName("app-name");
        addToDrawer(new Header(appName), new Scroller(createNavigation()));

        var toggle = new DrawerToggle();
        toggle.setAriaLabel("Menu toggle");
        viewTitle.addClassName("view-title");
        addToNavbar(true, toggle, viewTitle);
    }

    private SideNav createNavigation() {
        var nav = new SideNav();
        MenuConfiguration.getMenuEntries().forEach(entry -> {
            var item = new SideNavItem(entry.title(), entry.menuClass());
            if (entry.icon() != null) {
                item.setPrefixComponent(new Icon(entry.icon()));
            }
            nav.addItem(item);
        });
        return nav;
    }

